    if mean_val is None or (isinstance(mean_val, float) and math.isnan(mean_val)) or not (0 <= float(mean_val) <= 5):
        print(f"{label} Images: {info['n']} (Coll: {info['id']})")
        print(f"MeanAOD invalid: {mean_val}")
        return {'c3': True}

    pct = 100.0 * float(valid) / float(total)
    print(f"{label} Images: {info['n']} (Coll: {info['id']})")
    print(f"{label} ValidPix: {valid} / {total} ({pct:.1f}%), MeanAOD: {float(mean_val):.3f}")
    return {'mean': float(mean_val), 'nimg': info['n'], 'valid': int(valid), 'total': int(total)}

